import * as Dialog from "@radix-ui/react-dialog";
import Editor from "@monaco-editor/react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { Activity, Box, Code2, Container, Copy, Download, ExternalLink, FileText, ListTree, Pause, Play, RefreshCw, RotateCw, Search, ShieldAlert, Square, SquareTerminal, Trash2, X } from "lucide-react";
import { useEffect, useMemo, useRef, useState } from "react";
import { NavLink, useParams } from "react-router-dom";
import { Button } from "../../components/ui/Button";
import { api } from "../../lib/api";
import { errorMessage, isAppError } from "../../lib/errors";
import { formatBytes } from "../../lib/format";
import { dockerStatusLabel } from "../../lib/i18n";
import type { DockerComposeProject, DockerContainerInfo, DockerEventsResult, DockerLogs, DockerTextResult, RemoteTextFile } from "../../types/server";
import { useCommandTaskStore } from "../tasks/taskStore";

type PendingAction = { container: DockerContainerInfo; action: "start" | "stop" | "restart" | "pause" | "unpause" | "kill" | "remove" | "rename"; newName?: string };
type DetailKind = "inspect" | "stats" | "top";
type DockerDetail = DockerTextResult & { title: string };
type RunForm = { image: string; name: string; ports: string; environment: string; network: string; restartPolicy: string; autoRemove: boolean; privileged: boolean };
type BuildForm = { contextPath: string; dockerfilePath: string; image: string; buildArgs: string };
const initialRunForm: RunForm = { image: "nginx:latest", name: "", ports: "", environment: "", network: "", restartPolicy: "unless-stopped", autoRemove: false, privileged: false };
const initialBuildForm: BuildForm = { contextPath: "/opt/1panel-client/build-context", dockerfilePath: "", image: "1panel-client:latest", buildArgs: "" };

/** 按用户查询过滤当前容器日志，仅改变前端展示，不修改远端日志。 */
function filterLogOutput(output: string, query: string) {
  const needle = query.trim().toLocaleLowerCase();
  if (!needle) return output;
  return output.split("\n").filter((line) => line.toLocaleLowerCase().includes(needle)).join("\n");
}

/** 将 Docker inspect/stats JSON 统一格式化，普通文本结果保持原样。 */
function formatDockerDetail(output: string) {
  try {
    return JSON.stringify(JSON.parse(output), null, 2);
  } catch {
    return output;
  }
}

/** 将 Docker 日志导出为浏览器下载文件，不把日志写入服务器。 */
function downloadText(filename: string, content: string) {
  const blob = new Blob([content], { type: "text/plain;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  link.click();
  URL.revokeObjectURL(url);
}

/** 从 Docker 端口映射文本中提取第一个宿主端口，供本机浏览器打开。 */
function firstPublishedPort(ports: string) {
  const port = ports.match(/(\d+)->/)?.[1];
  return port ? Number(port) : null;
}

/** 按服务器地址打开容器发布端口，IPv6 地址会自动补方括号。 */
function openPublishedPort(host: string, port: number) {
  const normalizedHost = host.includes(":") && !host.startsWith("[") ? `[${host}]` : host;
  window.open(`http://${normalizedHost}:${port}`, "_blank", "noopener,noreferrer");
}

/** 展示远程 Docker CLI 数据，并把容器动作限制在确认后执行和验证。 */
export function DockerPage() {
  const { serverId = "" } = useParams();
  const queryClient = useQueryClient();
  const [query, setQuery] = useState("");
  const [statusFilter, setStatusFilter] = useState<"all" | "running" | "stopped" | "paused">("all");
  const [composeFilter, setComposeFilter] = useState("all");
  const [pending, setPending] = useState<PendingAction | null>(null);
  const [useSudo, setUseSudo] = useState(false);
  const [forceDelete, setForceDelete] = useState(false);
  const [logs, setLogs] = useState<DockerLogs | null>(null);
  const [logQuery, setLogQuery] = useState("");
  const [logTail, setLogTail] = useState(200);
  const [logsCleared, setLogsCleared] = useState(false);
  const [logsPaused, setLogsPaused] = useState(false);
  const [followOutput, setFollowOutput] = useState("");
  const [followTaskId, setFollowTaskId] = useState<string | null>(null);
  const followTaskRef = useRef<string | null>(null);
  const [execTarget, setExecTarget] = useState<DockerContainerInfo | null>(null);
  const [execCommand, setExecCommand] = useState("uname -a");
  const [execOutput, setExecOutput] = useState<DockerTextResult | null>(null);
  const [resourceTarget, setResourceTarget] = useState<{ kind: "volume" | "network" | "image" | "compose"; name: string; workingDir?: string; action: "create" | "remove" | "up" | "down" | "start" | "stop" | "restart" | "pull" | "build" | "cleanup" } | null>(null);
  const [detail, setDetail] = useState<DockerDetail | null>(null);
  const [detailQuery, setDetailQuery] = useState("");
  const [statsHistory, setStatsHistory] = useState<Array<{ at: string; output: string }>>([]);
  const [composeProject, setComposeProject] = useState<Pick<DockerComposeProject, "name" | "workingDir"> | null>(null);
  const [composeRawFile, setComposeRawFile] = useState<RemoteTextFile | null>(null);
  const [composeRawDraft, setComposeRawDraft] = useState("");
  const [composeEditing, setComposeEditing] = useState(false);
  const [composeLogs, setComposeLogs] = useState<DockerLogs | null>(null);
  const [eventsOpen, setEventsOpen] = useState(false);
  const [eventsSince, setEventsSince] = useState(300);
  const [runOpen, setRunOpen] = useState(false);
  const [runForm, setRunForm] = useState<RunForm>(initialRunForm);
  const [buildOpen, setBuildOpen] = useState(false);
  const [buildForm, setBuildForm] = useState<BuildForm>(initialBuildForm);
  const [buildOutput, setBuildOutput] = useState("");
  const [buildTaskId, setBuildTaskId] = useState<string | null>(null);
  const [pullImage, setPullImage] = useState("");
  const [pullOutput, setPullOutput] = useState("");
  const [pullTaskId, setPullTaskId] = useState<string | null>(null);
  const addTask = useCommandTaskStore((state) => state.add);
  const markRunning = useCommandTaskStore((state) => state.running);
  const markSuccess = useCommandTaskStore((state) => state.success);
  const markFail = useCommandTaskStore((state) => state.fail);
  const markCancelled = useCommandTaskStore((state) => state.cancelled);
  const resourceTaskRef = useRef<string | null>(null);
  const docker = useQuery({ queryKey: ["docker", serverId, useSudo], queryFn: () => api.docker(serverId, useSudo), enabled: !!serverId });
  const eventsMutation = useMutation<DockerEventsResult, unknown>({ mutationFn: () => api.dockerEvents(serverId, eventsSince, useSudo) });
  const profile = useQuery({ queryKey: ["server", serverId], queryFn: () => api.getServer(serverId), enabled: !!serverId });
  const composeDetails = useQuery({ queryKey: ["docker-compose", serverId, composeProject?.name, composeProject?.workingDir, useSudo], queryFn: () => api.dockerComposeDetails(serverId, composeProject!.name, composeProject!.workingDir || undefined, useSudo), enabled: !!composeProject });
  const action = useMutation({ mutationFn: () => api.dockerContainerAction({ serverId, containerId: pending!.container.id, action: pending!.action, newName: pending!.newName, force: pending!.action === "remove" && forceDelete, sudo: useSudo, confirmed: true }), onSuccess: async () => { setPending(null); setUseSudo(false); setForceDelete(false); await queryClient.invalidateQueries({ queryKey: ["docker", serverId] }); } });
  const logsMutation = useMutation({ mutationFn: (containerId: string) => api.dockerContainerLogs(serverId, containerId, logTail, useSudo), onSuccess: (value) => { setLogs(value); setLogQuery(""); setLogsCleared(false); setLogsPaused(false); } });
  const followMutation = useMutation({ mutationFn: (containerId: string) => { const taskId = crypto.randomUUID(); followTaskRef.current = taskId; setFollowTaskId(taskId); addTask({ id: taskId, type: "docker-follow", serverId, title: `跟随日志 ${containerId}`, status: "queued" }); return api.dockerContainerFollowLogs(serverId, containerId, 200, useSudo, taskId, (event) => { if (event.event === "output") { markRunning(taskId); setFollowOutput((current) => current + event.data.data); } if (event.event === "cancelled") markCancelled(taskId); }); }, onSuccess: (value) => { if (followTaskRef.current) markSuccess(followTaskRef.current); setLogs(value); }, onError: (reason) => { if (followTaskRef.current) { if (isAppError(reason) && reason.code === "CANCELLED") markCancelled(followTaskRef.current); else markFail(followTaskRef.current, errorMessage(reason)); } }, onSettled: () => { followTaskRef.current = null; setFollowTaskId(null); } });
  const execMutation = useMutation({ mutationFn: () => api.dockerContainerExec({ serverId, containerId: execTarget!.id, command: execCommand, sudo: useSudo }), onSuccess: setExecOutput });
  const resourceMutation = useMutation({ mutationFn: () => resourceTarget?.kind === "compose" ? api.dockerComposeAction({ serverId, project: resourceTarget.name, workingDir: resourceTarget.workingDir, action: resourceTarget.action as "up" | "down" | "start" | "stop" | "restart" | "pull" | "build" | "cleanup", sudo: useSudo, confirmed: true }) : resourceTarget?.kind === "image" ? api.dockerImageAction({ serverId, image: resourceTarget.name, action: "remove", force: false, sudo: useSudo, confirmed: true }) : api.dockerResourceAction({ serverId, kind: resourceTarget!.kind, name: resourceTarget!.name, action: resourceTarget!.action as "create" | "remove", sudo: useSudo, confirmed: true }), onMutate: () => { const taskId = crypto.randomUUID(); resourceTaskRef.current = taskId; addTask({ id: taskId, type: "docker-compose", serverId, title: `${resourceTarget?.kind ?? "Docker"} ${resourceTarget?.action ?? "操作"} · ${resourceTarget?.name ?? ""}`, status: "queued", cancelSupported: false }); markRunning(taskId); }, onSuccess: async () => { if (resourceTaskRef.current) markSuccess(resourceTaskRef.current); setResourceTarget(null); await queryClient.invalidateQueries({ queryKey: ["docker", serverId] }); await composeDetails.refetch(); }, onError: (reason) => { if (resourceTaskRef.current) markFail(resourceTaskRef.current, errorMessage(reason)); }, onSettled: () => { resourceTaskRef.current = null; } });
  const resourceInspectMutation = useMutation({ mutationFn: (input: { kind: "volume" | "network"; name: string }) => api.dockerResourceInspect({ serverId, ...input, sudo: useSudo }), onSuccess: (value, input) => setDetail({ ...value, title: `资源检查 · ${input.name}` }) });
  const composeLogsMutation = useMutation({ mutationFn: (service: string | undefined) => api.dockerComposeLogs(serverId, composeProject!.name, composeProject!.workingDir || undefined, service, 200, useSudo), onSuccess: setComposeLogs });
  const composeReadMutation = useMutation({ mutationFn: () => api.readText(serverId, composeDetails.data!.configPath!), onSuccess: (file) => { setComposeRawFile(file); setComposeRawDraft(file.content); setComposeEditing(true); } });
  const composeSaveMutation = useMutation({ mutationFn: () => api.dockerComposeSaveYaml({ serverId, project: composeProject!.name, workingDir: composeProject!.workingDir || undefined, configPath: composeRawFile!.path, content: composeRawDraft, expectedSize: composeRawFile!.size, expectedModifiedAt: composeRawFile!.modifiedAt, sudo: useSudo, confirmed: true }), onSuccess: async (file) => { setComposeRawFile(file); setComposeRawDraft(file.content); setComposeEditing(false); await composeDetails.refetch(); } });
  const detailMutation = useMutation({ mutationFn: ({ kind, containerId }: { kind: DetailKind; containerId: string }) => kind === "inspect" ? api.dockerContainerInspect(serverId, containerId, useSudo) : kind === "stats" ? api.dockerContainerStats(serverId, containerId, useSudo) : api.dockerContainerTop(serverId, containerId, useSudo), onSuccess: (value, variables) => { const output = formatDockerDetail(value.output); setDetail({ ...value, output, title: `${variables.kind === "inspect" ? "检查详情" : variables.kind === "stats" ? "资源统计" : "进程列表"} · ${variables.containerId}` }); setDetailQuery(""); if (variables.kind === "stats") setStatsHistory((current) => [...current, { at: new Date().toLocaleTimeString(), output }].slice(-12)); } });
  const pullMutation = useMutation({ mutationFn: (taskId: string) => { addTask({ id: taskId, type: "docker-pull", serverId, title: `拉取镜像 ${pullImage.trim()}`, status: "queued" }); return api.dockerPullImage({ serverId, image: pullImage.trim(), taskId, sudo: useSudo }, (event) => { if (event.event === "output") { markRunning(taskId); setPullOutput((current) => current + event.data.data); } if (event.event === "cancelled") markCancelled(taskId); }); }, onSuccess: async (_value, taskId) => { markSuccess(taskId); setPullImage(""); await queryClient.invalidateQueries({ queryKey: ["docker", serverId] }); }, onError: (reason, taskId) => { if (isAppError(reason) && reason.code === "CANCELLED") markCancelled(taskId); else markFail(taskId, errorMessage(reason)); }, onSettled: () => setPullTaskId(null) });
  const buildMutation = useMutation({ mutationFn: (taskId: string) => { const buildArgs = buildForm.buildArgs.split(/\n|,/).map((value) => value.trim()).filter(Boolean); addTask({ id: taskId, type: "docker-build", serverId, title: `构建镜像 ${buildForm.image.trim()}`, status: "queued" }); return api.dockerBuildImage({ serverId, contextPath: buildForm.contextPath.trim(), dockerfilePath: buildForm.dockerfilePath.trim() || undefined, image: buildForm.image.trim(), buildArgs, taskId, sudo: useSudo }, (event) => { if (event.event === "output") { markRunning(taskId); setBuildOutput((current) => current + event.data.data); } if (event.event === "cancelled") markCancelled(taskId); }); }, onSuccess: async (_value, taskId) => { markSuccess(taskId); setBuildOpen(false); setBuildForm(initialBuildForm); await queryClient.invalidateQueries({ queryKey: ["docker", serverId] }); }, onError: (reason, taskId) => { if (isAppError(reason) && reason.code === "CANCELLED") markCancelled(taskId); else markFail(taskId, errorMessage(reason)); }, onSettled: () => setBuildTaskId(null) });
  const runMutation = useMutation({ mutationFn: () => api.dockerRunContainer({ serverId, image: runForm.image.trim(), name: runForm.name.trim() || undefined, ports: runForm.ports.split(/[,\n]/).map((value) => value.trim()).filter(Boolean), environment: runForm.environment.split(/\n/).map((value) => value.trim()).filter(Boolean), network: runForm.network.trim() || undefined, restartPolicy: runForm.restartPolicy || undefined, autoRemove: runForm.autoRemove, privileged: runForm.privileged, sudo: useSudo }), onSuccess: async () => { setRunOpen(false); setRunForm(initialRunForm); await queryClient.invalidateQueries({ queryKey: ["docker", serverId] }); } });
  const filteredLogOutput = useMemo(() => filterLogOutput(logs?.output ?? "", logQuery), [logQuery, logs?.output]);
  const visibleLogOutput = logsCleared ? "" : filteredLogOutput;
  const filteredDetailOutput = useMemo(() => filterLogOutput(detail?.output ?? "", detailQuery), [detail?.output, detailQuery]);
  const containers = useMemo(() => docker.data?.containers.filter((container) => { const haystack = [container.name, container.id, container.image, container.status, container.ports, container.composeProject].some((value) => (value ?? "").toLocaleLowerCase().includes(query.trim().toLocaleLowerCase())); const normalizedStatus = container.status.toLocaleLowerCase(); const statusMatches = statusFilter === "all" || (statusFilter === "running" && normalizedStatus.startsWith("up")) || (statusFilter === "paused" && normalizedStatus.includes("paused")) || (statusFilter === "stopped" && !normalizedStatus.startsWith("up")); const composeMatches = composeFilter === "all" || container.composeProject === composeFilter; return haystack && statusMatches && composeMatches; }) ?? [], [composeFilter, docker.data, query, statusFilter]);
  const composeProjects = useMemo(() => Array.from(new Set((docker.data?.containers ?? []).map((container) => container.composeProject).filter((value): value is string => !!value))).sort(), [docker.data]);

  useEffect(() => {
    if (!detail?.title.startsWith("stats")) return;
    const timer = window.setInterval(() => detailMutation.mutate({ kind: "stats", containerId: detail.containerId }), 5000);
    return () => window.clearInterval(timer);
  }, [detail?.containerId, detail?.title, detailMutation, useSudo]);

  return <section className="docker-page">
    <div className="workspace-header"><div><div className="breadcrumb">服务器 / <span>Docker</span></div><h1>Docker</h1><p>SSH 通道 · 容器与镜像现场</p></div><div className="workspace-header__actions"><Button variant="secondary" onClick={() => { setEventsOpen(true); eventsMutation.mutate(); }} disabled={eventsMutation.isPending}><Activity size={14} />事件</Button><Button variant="secondary" onClick={() => docker.refetch()} disabled={docker.isFetching}><RefreshCw className={docker.isFetching ? "spin" : ""} size={14} /> 刷新</Button></div></div>
    <DockerTabs serverId={serverId} />
    {followTaskId && <div className="page-state"><span>正在跟随容器日志，最多 30 秒。</span><Button size="sm" variant="danger" onClick={() => void api.cancelCommandTask(followTaskId)}>取消远端跟随</Button></div>}
    {docker.isLoading && <div className="page-state">正在读取 Docker 引擎、容器和镜像…</div>}
    {docker.error && <div className="page-state page-state--error">{errorMessage(docker.error)}</div>}
    {logsMutation.error && <div className="page-state page-state--error">{errorMessage(logsMutation.error)}</div>}
    {detailMutation.error && <div className="page-state page-state--error">{errorMessage(detailMutation.error)}</div>}
    {resourceInspectMutation.error && <div className="page-state page-state--error">{errorMessage(resourceInspectMutation.error)}</div>}
    {pullMutation.error && <div className="page-state page-state--error">{errorMessage(pullMutation.error)}</div>}
    {buildMutation.isError && <div className="page-state page-state--error">{errorMessage(buildMutation.error)}</div>}
    {eventsMutation.isError && <div className="page-state page-state--error">{errorMessage(eventsMutation.error)}</div>}
    {docker.data && (!docker.data.installed ? <div className="empty-panel"><Container size={27} /><h2>尚未安装 Docker</h2><p>请在工具中心查看 Docker 安装计划；本应用不会开启 Docker TCP API。</p></div> : <>
      <div className="docker-summary"><div><span>引擎版本</span><strong>{docker.data.version ?? "未知"}</strong></div><div><span>接口版本</span><strong>{docker.data.apiVersion ?? "未知"}</strong></div><div><span>系统</span><strong>{docker.data.os ?? "未知"} / {docker.data.architecture ?? "未知"}</strong></div><div><span>存储驱动</span><strong>{docker.data.storageDriver ?? "未知"}</strong><small className="mono">{docker.data.rootDir ?? "根目录未返回"}</small></div><div><span>资源总览</span><strong>{docker.data.containers.length} 个容器 · {docker.data.images.length} 个镜像</strong><small>{docker.data.volumes.length} 个卷 · {docker.data.networks.length} 个网络</small></div></div>
      <div className="docker-toolbar"><label><Search size={15} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="筛选容器名称、镜像、端口" /></label><label className="hidden-toggle">状态<select value={statusFilter} onChange={(event) => setStatusFilter(event.target.value as typeof statusFilter)}><option value="all">全部</option><option value="running">运行中</option><option value="stopped">已停止</option><option value="paused">已暂停</option></select></label><label className="hidden-toggle">Compose<select value={composeFilter} onChange={(event) => setComposeFilter(event.target.value)}><option value="all">全部项目</option>{composeProjects.map((project) => <option key={project} value={project}>{project}</option>)}</select></label>{profile.data && profile.data.sudoMode !== "none" && <label className="force-toggle"><input type="checkbox" checked={useSudo} onChange={(event) => setUseSudo(event.target.checked)} /> 使用 sudo 读取/操作</label>}<span>{containers.length} / {docker.data.containers.length}</span></div>
      <section className="docker-section"><header><Container size={15} /><strong>容器</strong><span>{containers.length}</span></header>{containers.length ? <div className="docker-table"><div className="ops-head"><span>名称</span><span>镜像</span><span>状态</span><span>端口</span><span>操作</span></div>{containers.map((container) => <ContainerRow key={container.id} container={container} onAction={(actionName, newName) => { setPending({ container, action: actionName, newName }); setForceDelete(false); }} onOpenPort={(port) => profile.data && openPublishedPort(profile.data.host, port)} onLogs={() => logsMutation.mutate(container.id)} onFollow={() => { setFollowOutput(""); followMutation.mutate(container.id); }} onExec={() => { setExecTarget(container); setExecOutput(null); setExecCommand("uname -a"); }} onDetail={(kind) => detailMutation.mutate({ kind, containerId: container.id })} />)}</div> : <div className="empty-panel empty-panel--small">没有匹配的容器。</div>}</section>
      <section className="docker-section"><header><Box size={15} /><strong>镜像</strong><span>{docker.data.images.length}</span><div className="docker-image-tools"><input value={pullImage} onChange={(event) => setPullImage(event.target.value)} placeholder="nginx:latest" />{pullMutation.isPending ? <Button size="sm" variant="danger" onClick={() => pullTaskId && void api.cancelCommandTask(pullTaskId)}>取消拉取</Button> : <Button size="sm" variant="secondary" onClick={() => { const taskId = crypto.randomUUID(); setPullTaskId(taskId); setPullOutput(""); pullMutation.mutate(taskId); }} disabled={!pullImage.trim()}>拉取</Button>}<Button size="sm" variant="ghost" onClick={() => { setBuildOutput(""); setBuildOpen(true); }}>构建</Button><Button size="sm" variant="ghost" onClick={() => setRunOpen(true)}>运行</Button></div></header><div className="docker-table"><div className="ops-head docker-images-head"><span>仓库</span><span>标签</span><span>ID</span><span>大小</span><span>创建时间</span><span>操作</span></div>{docker.data.images.map((image) => <div className="ops-row docker-images-row" key={`${image.id}:${image.tag}`}><strong>{image.repository}</strong><span className="mono">{image.tag}</span><span className="mono">{image.id}</span><span>{image.size}</span><span>{image.created}</span><span><Button size="sm" variant="danger" onClick={() => setResourceTarget({ kind: "image", name: image.repository === "<none>" || image.tag === "<none>" ? image.id : `${image.repository}:${image.tag}`, action: "remove" })}>删除</Button></span></div>)}</div>{pullOutput && <pre className="install-output docker-pull-output">{pullOutput}</pre>}</section>
      <section className="docker-section"><header><Activity size={15} /><strong>卷 / 网络 / Compose</strong><span>{docker.data.volumes.length} / {docker.data.networks.length} / {docker.data.composeProjects.length}</span></header><div className="docker-resource-grid"><div><strong>卷</strong><Button size="sm" variant="ghost" onClick={() => { const name = window.prompt("新 volume 名称"); if (name) setResourceTarget({ kind: "volume", name, action: "create" }); }}>新建</Button>{docker.data.volumes.length ? docker.data.volumes.map((volume) => <div className="docker-resource-row" key={volume.name}><span className="mono">{volume.name}</span><small>{volume.driver} · {volume.mountpoint}</small><span className="docker-actions"><Button size="sm" variant="ghost" onClick={() => resourceInspectMutation.mutate({ kind: "volume", name: volume.name })}>检查</Button><Button size="sm" variant="danger" onClick={() => setResourceTarget({ kind: "volume", name: volume.name, action: "remove" })}>删除</Button></span></div>) : <small>没有返回卷。</small>}</div><div><strong>网络</strong><Button size="sm" variant="ghost" onClick={() => { const name = window.prompt("新 network 名称"); if (name) setResourceTarget({ kind: "network", name, action: "create" }); }}>新建</Button>{docker.data.networks.length ? docker.data.networks.map((network) => <div className="docker-resource-row" key={network.id}><span>{network.name}</span><small>{network.driver} · {network.scope}</small><span className="docker-actions"><Button size="sm" variant="ghost" onClick={() => resourceInspectMutation.mutate({ kind: "network", name: network.name })}>检查</Button><Button size="sm" variant="danger" onClick={() => setResourceTarget({ kind: "network", name: network.name, action: "remove" })}>删除</Button></span></div>) : <small>没有返回网络。</small>}</div><div><strong>Compose 项目</strong>{docker.data.composeProjects.length ? docker.data.composeProjects.map((project) => <div className="docker-resource-row" key={project.name}><span>{project.name} · {project.status}</span><small>{project.workingDir || project.configFiles || "配置路径未返回"}</small><span className="docker-actions"><Button size="sm" variant="ghost" onClick={() => setComposeProject({ name: project.name, workingDir: project.workingDir })}>详情</Button><Button size="sm" variant="ghost" onClick={() => setResourceTarget({ kind: "compose", name: project.name, workingDir: project.workingDir || undefined, action: "up" })}>启动</Button><Button size="sm" variant="ghost" onClick={() => setResourceTarget({ kind: "compose", name: project.name, workingDir: project.workingDir || undefined, action: "restart" })}>重启</Button><Button size="sm" variant="ghost" onClick={() => setResourceTarget({ kind: "compose", name: project.name, workingDir: project.workingDir || undefined, action: "pull" })}>拉取</Button><Button size="sm" variant="ghost" onClick={() => setResourceTarget({ kind: "compose", name: project.name, workingDir: project.workingDir || undefined, action: "build" })}>构建</Button><Button size="sm" variant="danger" onClick={() => setResourceTarget({ kind: "compose", name: project.name, workingDir: project.workingDir || undefined, action: "stop" })}>停止</Button><Button size="sm" variant="danger" onClick={() => setResourceTarget({ kind: "compose", name: project.name, workingDir: project.workingDir || undefined, action: "down" })}>停止并移除</Button></span></div>) : <small>未发现 Compose v2 项目。</small>}</div></div></section>
        {docker.data.composeProjects.length > 0 && <section className="docker-section"><header><ShieldAlert size={15} /><strong>Compose 清理预览</strong><span>先打开详情确认服务、卷和网络</span></header><div className="docker-resource-grid"><div><strong>项目资源</strong>{docker.data.composeProjects.map((project) => <div className="docker-resource-row" key={`cleanup-${project.name}`}><span><strong>{project.name}</strong><small>{project.workingDir || project.configFiles || "配置路径未返回"}</small></span><span className="docker-actions"><Button size="sm" variant="ghost" onClick={() => setComposeProject({ name: project.name, workingDir: project.workingDir })}>查看预览</Button><Button size="sm" variant="danger" onClick={() => setResourceTarget({ kind: "compose", name: project.name, workingDir: project.workingDir || undefined, action: "cleanup" })}>清理项目</Button></span></div>)}</div></div></section>}
      </>)}
    <Dialog.Root open={eventsOpen} onOpenChange={setEventsOpen}><Dialog.Portal><Dialog.Overlay className="dialog-overlay" /><Dialog.Content className="dialog-content docker-logs-dialog"><div className="dialog-header"><div><Dialog.Title>Docker 事件</Dialog.Title><Dialog.Description>读取最近一段 daemon 事件，仅展示有限字段，不保存原始 actor 属性。</Dialog.Description></div><Dialog.Close asChild><button className="icon-control" aria-label="关闭"><X size={17} /></button></Dialog.Close></div><div className="docker-log-toolbar"><label><span>时间范围</span><select value={eventsSince} onChange={(event) => setEventsSince(Number(event.target.value))}><option value={60}>最近 1 分钟</option><option value={300}>最近 5 分钟</option><option value={900}>最近 15 分钟</option><option value={3600}>最近 1 小时</option></select></label><Button size="sm" variant="ghost" onClick={() => eventsMutation.mutate()} disabled={eventsMutation.isPending}><RefreshCw size={13} className={eventsMutation.isPending ? "spin" : ""} />刷新</Button></div>{eventsMutation.isPending && <div className="page-state">正在读取 Docker daemon 事件…</div>}{eventsMutation.data ? <div className="docker-events-list">{eventsMutation.data.events.length ? eventsMutation.data.events.slice().reverse().map((event, index) => <div className="docker-event-row" key={`${event.timestamp ?? "none"}-${event.action}-${index}`}><span className="mono">{event.timestamp ? new Date(event.timestamp * 1000).toLocaleString() : "—"}</span><strong>{event.eventType}</strong><span>{event.action}</span><small>{event.actorName || event.actorId || "未知对象"}</small></div>) : <div className="empty-panel empty-panel--small"><Activity size={20} /><span>时间范围内没有 Docker 事件。</span></div>}<small className="docker-events-footnote">获取于 {new Date(eventsMutation.data.fetchedAt).toLocaleString()} · 最多显示 200 条</small></div> : !eventsMutation.isPending && <div className="empty-panel empty-panel--small"><Activity size={20} /><span>点击刷新读取事件。</span></div>}</Dialog.Content></Dialog.Portal></Dialog.Root>
    <Dialog.Root open={buildOpen} onOpenChange={(open) => { setBuildOpen(open); if (!open && !buildMutation.isPending) setBuildOutput(""); }}><Dialog.Portal><Dialog.Overlay className="dialog-overlay" /><Dialog.Content className="dialog-content docker-logs-dialog"><div className="dialog-header"><div><Dialog.Title>构建 Docker 镜像</Dialog.Title><Dialog.Description>在目标服务器上执行 docker build；上下文目录必须是远端绝对路径，输出仅在本页和任务中心显示。</Dialog.Description></div><Dialog.Close asChild><button className="icon-control" aria-label="关闭" disabled={buildMutation.isPending}><X size={17} /></button></Dialog.Close></div><form className="server-form" onSubmit={(event) => { event.preventDefault(); const taskId = crypto.randomUUID(); setBuildTaskId(taskId); setBuildOutput(""); buildMutation.mutate(taskId); }}><div className="field-grid field-grid--2"><label><span>构建上下文目录</span><input required value={buildForm.contextPath} onChange={(event) => setBuildForm((current) => ({ ...current, contextPath: event.target.value }))} placeholder="/opt/app" /></label><label><span>镜像标签</span><input required value={buildForm.image} onChange={(event) => setBuildForm((current) => ({ ...current, image: event.target.value }))} placeholder="example/app:latest" /></label></div><label><span>Dockerfile 路径（可选，远端路径）</span><input value={buildForm.dockerfilePath} onChange={(event) => setBuildForm((current) => ({ ...current, dockerfilePath: event.target.value }))} placeholder="Dockerfile 或 /opt/app/Dockerfile.prod" /></label><label><span>构建参数（每行 KEY=VALUE）</span><textarea rows={4} value={buildForm.buildArgs} onChange={(event) => setBuildForm((current) => ({ ...current, buildArgs: event.target.value }))} placeholder="NODE_ENV=production" /></label>{buildMutation.error && <div className="form-error">{errorMessage(buildMutation.error)}</div>}<div className="dialog-actions"><Button type="button" variant="ghost" onClick={() => setBuildOpen(false)} disabled={buildMutation.isPending}>关闭</Button>{buildMutation.isPending ? <Button type="button" variant="danger" onClick={() => buildTaskId && void api.cancelCommandTask(buildTaskId)}>取消构建</Button> : <Button type="submit" variant="primary" disabled={!buildForm.contextPath.trim() || !buildForm.image.trim()}>开始构建</Button>}</div></form>{buildOutput && <pre className="docker-logs docker-build-output">{buildOutput}</pre>}</Dialog.Content></Dialog.Portal></Dialog.Root>
    <Dialog.Root open={runOpen} onOpenChange={setRunOpen}><Dialog.Portal><Dialog.Overlay className="dialog-overlay" /><Dialog.Content className="dialog-content"><div className="dialog-header"><div><Dialog.Title>Run Container</Dialog.Title><Dialog.Description>执行前只生成受控 docker run 参数，成功后 inspect 验证。</Dialog.Description></div><Dialog.Close asChild><button className="icon-control" aria-label="关闭"><X size={17} /></button></Dialog.Close></div><form className="server-form" onSubmit={(event) => { event.preventDefault(); runMutation.mutate(); }}><div className="field-grid field-grid--2"><label><span>镜像</span><input required value={runForm.image} onChange={(event) => setRunForm((current) => ({ ...current, image: event.target.value }))} /></label><label><span>名称</span><input value={runForm.name} onChange={(event) => setRunForm((current) => ({ ...current, name: event.target.value }))} placeholder="可选" /></label></div><div className="field-grid field-grid--2"><label><span>端口映射</span><input value={runForm.ports} onChange={(event) => setRunForm((current) => ({ ...current, ports: event.target.value }))} placeholder="8080:80, 8443:443" /></label><label><span>网络</span><input value={runForm.network} onChange={(event) => setRunForm((current) => ({ ...current, network: event.target.value }))} placeholder="可选" /></label></div><label><span>环境变量（每行 KEY=VALUE）</span><textarea rows={4} value={runForm.environment} onChange={(event) => setRunForm((current) => ({ ...current, environment: event.target.value }))} /></label><div className="field-grid field-grid--2"><label><span>重启策略</span><select value={runForm.restartPolicy} onChange={(event) => setRunForm((current) => ({ ...current, restartPolicy: event.target.value }))}><option value="no">no</option><option value="unless-stopped">unless-stopped</option><option value="always">always</option><option value="on-failure:5">on-failure:5</option></select></label><div className="run-checks"><label className="check-field"><input type="checkbox" checked={runForm.autoRemove} onChange={(event) => setRunForm((current) => ({ ...current, autoRemove: event.target.checked }))} /><span>容器退出后自动删除</span></label><label className="check-field"><input type="checkbox" checked={runForm.privileged} onChange={() => setRunForm((current) => ({ ...current, privileged: !current.privileged }))} /><span>以 privileged 运行（高风险）</span></label></div></div>{runMutation.error && <div className="form-error">{errorMessage(runMutation.error)}</div>}<div className="dialog-actions"><Button type="button" variant="ghost" onClick={() => setRunOpen(false)}>取消</Button><Button type="submit" variant={runForm.privileged ? "danger" : "primary"} disabled={runMutation.isPending}>{runMutation.isPending ? "创建并验证中…" : runForm.privileged ? "确认高风险 Run" : "创建容器"}</Button></div></form></Dialog.Content></Dialog.Portal></Dialog.Root>
    <Dialog.Root open={!!pending} onOpenChange={(open) => { if (!open) { setPending(null); setUseSudo(false); setForceDelete(false); } }}><Dialog.Portal><Dialog.Overlay className="dialog-overlay" /><Dialog.Content className="dialog-content dialog-content--narrow confirm-dialog"><Dialog.Title>{pending?.action === "remove" ? "删除容器" : pending?.action === "rename" ? "重命名容器" : `确认 ${pending?.action}`}</Dialog.Title><Dialog.Description>将对容器 <strong>{pending?.container.name}</strong>（{pending?.container.id}）执行 {pending?.action}{pending?.newName ? `，新名称为 ${pending.newName}` : ""}，随后重新读取状态。</Dialog.Description>{pending?.action === "remove" && <label className="force-toggle"><input type="checkbox" checked={forceDelete} onChange={(event) => setForceDelete(event.target.checked)} /> 强制删除（运行中的容器也会被停止）</label>}{profile.data && profile.data.sudoMode !== "none" && <label className="force-toggle"><input type="checkbox" checked={useSudo} onChange={(event) => setUseSudo(event.target.checked)} /> 使用已配置的 sudo</label>}{action.error && <div className="form-error">{errorMessage(action.error)}</div>}<div className="dialog-actions"><Button variant="ghost" onClick={() => { setPending(null); setUseSudo(false); setForceDelete(false); }}>取消</Button><Button variant={pending?.action === "remove" || pending?.action === "kill" ? "danger" : "primary"} onClick={() => action.mutate()} disabled={action.isPending}>{action.isPending ? "执行并验证中…" : pending?.action === "remove" && forceDelete ? "确认强制删除" : pending?.action === "rename" ? "确认重命名" : "确认执行"}</Button></div></Dialog.Content></Dialog.Portal></Dialog.Root>
    <Dialog.Root open={!!logs} onOpenChange={(open) => !open && setLogs(null)}><Dialog.Portal><Dialog.Overlay className="dialog-overlay" /><Dialog.Content className="dialog-content docker-logs-dialog"><div className="dialog-header"><div><Dialog.Title>容器日志</Dialog.Title><Dialog.Description>{logs?.containerId} · 最近 {logTail} 行{logsPaused ? " · 已暂停刷新" : ""}</Dialog.Description></div><Dialog.Close asChild><button className="icon-control" aria-label="关闭"><X size={17} /></button></Dialog.Close></div><div className="docker-log-toolbar"><label><Search size={14} /><input value={logQuery} onChange={(event) => setLogQuery(event.target.value)} placeholder="筛选日志文本" /></label><label className="docker-log-tail"><span>行数</span><select value={logTail} onChange={(event) => setLogTail(Number(event.target.value))}><option value={100}>100</option><option value={200}>200</option><option value={500}>500</option><option value={1000}>1000</option></select></label><Button size="sm" variant="ghost" onClick={() => setLogsPaused((paused) => !paused)}><Pause size={13} /> {logsPaused ? "继续" : "暂停"}</Button><Button size="sm" variant="ghost" onClick={() => setLogsCleared(true)} disabled={logsCleared}><Trash2 size={13} /> 清空视图</Button><Button size="sm" variant="ghost" onClick={() => logs && logsMutation.mutate(logs.containerId)} disabled={!logs || logsMutation.isPending}><RefreshCw size={13} className={logsMutation.isPending ? "spin" : ""} /> 刷新</Button><Button size="sm" variant="ghost" onClick={() => void navigator.clipboard?.writeText(visibleLogOutput)}><Copy size={13} /> 复制</Button><Button size="sm" variant="ghost" onClick={() => downloadText(`docker-${logs?.containerId ?? "logs"}.log`, visibleLogOutput)}><Download size={13} /> 下载</Button></div><pre className="docker-logs">{visibleLogOutput || "没有匹配的日志。"}</pre></Dialog.Content></Dialog.Portal></Dialog.Root>
    <Dialog.Root open={!!followOutput || followMutation.isPending} onOpenChange={() => undefined}><Dialog.Portal><Dialog.Overlay className="dialog-overlay" /><Dialog.Content className="dialog-content docker-logs-dialog"><div className="dialog-header"><div><Dialog.Title>实时日志（最多 30 秒）</Dialog.Title><Dialog.Description>日志跟随会自动结束，避免遗留远程任务</Dialog.Description></div><Button variant="ghost" size="sm" onClick={() => setFollowOutput("")}>关闭</Button></div><pre className="docker-logs">{followOutput || (followMutation.isPending ? "正在等待日志…" : "没有输出")}</pre></Dialog.Content></Dialog.Portal></Dialog.Root>
    <Dialog.Root open={!!execTarget} onOpenChange={(open) => !open && setExecTarget(null)}><Dialog.Portal><Dialog.Overlay className="dialog-overlay" /><Dialog.Content className="dialog-content docker-logs-dialog"><div className="dialog-header"><div><Dialog.Title>容器命令 · {execTarget?.name}</Dialog.Title><Dialog.Description>命令在容器内执行，结果只读显示，不保存到本地。</Dialog.Description></div><Dialog.Close asChild><button className="icon-control" aria-label="关闭"><X size={17} /></button></Dialog.Close></div><form className="server-form" onSubmit={(event) => { event.preventDefault(); execMutation.mutate(); }}><label><span>命令</span><input value={execCommand} onChange={(event) => setExecCommand(event.target.value)} /></label>{execMutation.error && <div className="form-error">{errorMessage(execMutation.error)}</div>}<div className="dialog-actions"><Button type="submit" variant="primary" disabled={execMutation.isPending}>{execMutation.isPending ? "执行中…" : "执行"}</Button></div></form>{execOutput && <pre className="docker-logs">{execOutput.output}</pre>}</Dialog.Content></Dialog.Portal></Dialog.Root>
    <Dialog.Root open={!!resourceTarget} onOpenChange={(open) => !open && setResourceTarget(null)}><Dialog.Portal><Dialog.Overlay className="dialog-overlay" /><Dialog.Content className="dialog-content dialog-content--narrow confirm-dialog"><div className="destructive-icon"><ShieldAlert size={22} /></div><Dialog.Title>确认 Docker 资源操作</Dialog.Title><Dialog.Description>{resourceTarget?.action === "remove" ? "该操作会删除远端 Docker 资源；执行后会重新读取并验证结果。" : resourceTarget?.action === "down" || resourceTarget?.action === "stop" ? "该操作会停止 Compose 项目中的服务。" : resourceTarget?.action === "cleanup" ? "这会执行 Compose down --remove-orphans --volumes，停止项目并删除声明的卷。" : "将对远端 Docker 资源执行操作。"} 目标：{resourceTarget?.name}</Dialog.Description>{resourceMutation.error && <div className="form-error">{errorMessage(resourceMutation.error)}</div>}<div className="dialog-actions"><Button variant="ghost" onClick={() => setResourceTarget(null)}>取消</Button><Button variant={resourceTarget?.action === "remove" || resourceTarget?.action === "down" || resourceTarget?.action === "stop" || resourceTarget?.action === "cleanup" ? "danger" : "primary"} onClick={() => resourceMutation.mutate()} disabled={resourceMutation.isPending}>{resourceMutation.isPending ? "执行并验证中…" : "确认执行"}</Button></div></Dialog.Content></Dialog.Portal></Dialog.Root>
    <Dialog.Root open={!!detail} onOpenChange={(open) => !open && setDetail(null)}><Dialog.Portal><Dialog.Overlay className="dialog-overlay" /><Dialog.Content className="dialog-content docker-logs-dialog"><div className="dialog-header"><div><Dialog.Title>{detail?.title}</Dialog.Title><Dialog.Description>{detail?.title.startsWith("stats") ? `只读 Docker CLI 结果 · ${statsHistory.length} 个本页采样` : "只读 Docker CLI 结果"}</Dialog.Description></div><Dialog.Close asChild><button className="icon-control" aria-label="关闭"><X size={17} /></button></Dialog.Close></div><div className="docker-log-toolbar"><label><Search size={14} /><input value={detailQuery} onChange={(event) => setDetailQuery(event.target.value)} placeholder="搜索 JSON / 输出" /></label><Button size="sm" variant="ghost" onClick={() => void navigator.clipboard?.writeText(filteredDetailOutput)}><Copy size={13} /> 复制</Button>{detail?.title.startsWith("stats") && <Button size="sm" variant="ghost" onClick={() => detailMutation.mutate({ kind: "stats", containerId: detail.containerId })} disabled={detailMutation.isPending}><RefreshCw size={13} className={detailMutation.isPending ? "spin" : ""} /> 采样</Button>}</div><pre className="docker-logs">{filteredDetailOutput || "没有匹配的结果。"}</pre>{detail?.title.startsWith("stats") && statsHistory.length > 1 && <div className="docker-stats-history">{statsHistory.slice().reverse().map((sample) => <div key={sample.at}><span>{sample.at}</span><code>{sample.output.slice(0, 160)}</code></div>)}</div>}</Dialog.Content></Dialog.Portal></Dialog.Root>
    <Dialog.Root open={!!composeProject} onOpenChange={(open) => { if (!open) { setComposeProject(null); setComposeRawFile(null); setComposeEditing(false); } }}><Dialog.Portal><Dialog.Overlay className="dialog-overlay" /><Dialog.Content className="dialog-content docker-logs-dialog"><div className="dialog-header"><div><Dialog.Title>Compose · {composeProject?.name}</Dialog.Title><Dialog.Description>服务状态、渲染配置和清理候选；原始 YAML 只有在明确点击编辑后才读取。</Dialog.Description></div><Dialog.Close asChild><button className="icon-control" aria-label="关闭"><X size={17} /></button></Dialog.Close></div>{composeDetails.isLoading && <div className="page-state">正在读取 Compose 服务和配置…</div>}{composeDetails.error && <div className="page-state page-state--error">{errorMessage(composeDetails.error)}</div>}{composeDetails.data && <div className="compose-details"><section><div className="compose-details__heading"><strong>服务</strong><span>{composeDetails.data.services.length}</span><Button size="sm" variant="ghost" onClick={() => composeLogsMutation.mutate(undefined)}>项目日志</Button></div>{composeDetails.data.services.length ? composeDetails.data.services.map((service) => <div className="compose-service-row" key={service.name}><span><strong>{service.service || service.name}</strong><small className="mono">{service.name} · {service.image}</small></span><span>{service.state || "未知"} {service.status && `· ${service.status}`}</span><span>{service.ports || "—"}</span><Button size="sm" variant="ghost" onClick={() => composeLogsMutation.mutate(service.service || service.name)}>日志</Button></div>) : <small>没有返回服务。</small>}</section><section><div className="compose-details__heading"><strong>{composeEditing ? "原始 YAML 编辑器" : "渲染配置（默认脱敏）"}</strong><span>{composeRawFile?.path ?? composeDetails.data.configPath ?? "docker compose config"}</span><span>{composeEditing ? <><Button size="sm" variant="ghost" onClick={() => { setComposeEditing(false); setComposeRawFile(null); }}>取消</Button><Button size="sm" variant="primary" onClick={() => void composeSaveMutation.mutate()} disabled={composeSaveMutation.isPending || !composeRawFile}>{composeSaveMutation.isPending ? "校验并保存中…" : "保存并校验"}</Button></> : <Button size="sm" variant="ghost" onClick={() => void composeReadMutation.mutate()} disabled={!composeDetails.data.configPath || composeReadMutation.isPending}>{composeReadMutation.isPending ? "读取中…" : "编辑原始 YAML"}</Button>}</span></div>{composeSaveMutation.error && <div className="form-error">{errorMessage(composeSaveMutation.error)}</div>}{composeEditing && <div className="security-note"><ShieldAlert size={16} /><span>保存前会执行 <code>docker compose config -q</code>；失败自动恢复原文件。敏感值不会在默认脱敏配置中显示，请确认编辑内容完整。</span></div>}<Editor height="280px" defaultLanguage="yaml" value={composeEditing ? composeRawDraft : composeDetails.data.config} onChange={(next) => composeEditing && setComposeRawDraft(next ?? "")} theme="vs-dark" options={{ readOnly: !composeEditing, minimap: { enabled: false }, wordWrap: "on", automaticLayout: true, scrollBeyondLastLine: false }} /></section><div className="compose-cleanup-grid"><section><div className="compose-details__heading"><strong>Compose 卷</strong><span>{composeDetails.data.volumes.length}</span></div>{composeDetails.data.volumes.map((name) => <div className="docker-resource-row" key={name}><span className="mono">{name}</span><Button size="sm" variant="danger" onClick={() => setResourceTarget({ kind: "volume", name, action: "remove" })}>逐项删除</Button></div>)}{!composeDetails.data.volumes.length && <small>没有声明卷。</small>}</section><section><div className="compose-details__heading"><strong>Compose 网络</strong><span>{composeDetails.data.networks.length}</span></div>{composeDetails.data.networks.map((name) => <div className="docker-resource-row" key={name}><span className="mono">{name}</span><Button size="sm" variant="danger" onClick={() => setResourceTarget({ kind: "network", name, action: "remove" })}>逐项删除</Button></div>)}{!composeDetails.data.networks.length && <small>没有声明网络。</small>}</section></div><section className="compose-cleanup-preview"><div className="compose-details__heading"><strong>实际 cleanup 候选</strong><span>{composeDetails.data.cleanupVolumes.length + composeDetails.data.cleanupNetworks.length + composeDetails.data.orphanContainers.length}</span></div><small>以下资源来自远端 Docker 的 Compose project label；只读预览不会执行删除。</small>{composeDetails.data.cleanupVolumes.map((name) => <div className="docker-resource-row" key={`cleanup-volume-${name}`}><span>卷 · <span className="mono">{name}</span></span></div>)}{composeDetails.data.cleanupNetworks.map((name) => <div className="docker-resource-row" key={`cleanup-network-${name}`}><span>网络 · <span className="mono">{name}</span></span></div>)}{composeDetails.data.orphanContainers.map((name) => <div className="docker-resource-row" key={`cleanup-orphan-${name}`}><span className="text-warn">孤儿容器 · <span className="mono">{name}</span></span></div>)}{!composeDetails.data.cleanupVolumes.length && !composeDetails.data.cleanupNetworks.length && !composeDetails.data.orphanContainers.length && <small>没有发现带 project label 的可清理资源。</small>}{composeDetails.data.cleanupWarnings.map((warning) => <div className="warning-panel" key={warning}><ShieldAlert size={14} /><span>{warning}</span></div>)}</section></div>}</Dialog.Content></Dialog.Portal></Dialog.Root>
    <Dialog.Root open={!!composeLogs || composeLogsMutation.isPending} onOpenChange={(open) => !open && setComposeLogs(null)}><Dialog.Portal><Dialog.Overlay className="dialog-overlay" /><Dialog.Content className="dialog-content docker-logs-dialog"><div className="dialog-header"><div><Dialog.Title>Compose 日志</Dialog.Title><Dialog.Description>{composeLogs?.containerId} · 最近 200 行</Dialog.Description></div><Dialog.Close asChild><button className="icon-control" aria-label="关闭"><X size={17} /></button></Dialog.Close></div>{composeLogsMutation.error && <div className="form-error">{errorMessage(composeLogsMutation.error)}</div>}<pre className="docker-logs">{composeLogs?.output || (composeLogsMutation.isPending ? "正在读取日志…" : "没有输出")}</pre></Dialog.Content></Dialog.Portal></Dialog.Root>
  </section>;
}

/** 渲染容器状态、确认动作、复制入口和只读详情入口。 */
function ContainerRow({ container, onAction, onOpenPort, onLogs, onFollow, onExec, onDetail }: { container: DockerContainerInfo; onAction: (action: PendingAction["action"], newName?: string) => void; onOpenPort: (port: number) => void; onLogs: () => void; onFollow: () => void; onExec: () => void; onDetail: (kind: DetailKind) => void }) {
  const running = container.status.toLocaleLowerCase().startsWith("up");
  const paused = container.status.toLocaleLowerCase().includes("paused");
  const publishedPort = firstPublishedPort(container.ports);
  return <article className="docker-container-card"><div className="docker-container-main"><div className="docker-container-identity"><span className={`docker-status-dot ${running ? "is-running" : ""}`} /><div><strong>{container.name}</strong><small className="mono">{container.id}</small></div></div><div className="docker-container-image"><span className="docker-label">镜像</span><strong className="mono">{container.image}</strong></div><div className="docker-container-state"><span className={running ? "text-ok" : "text-warn"}>{dockerStatusLabel(container.status)}</span><small>{container.health ? `健康：${container.health}` : ""}{container.created ? ` · ${container.created}` : ""}{container.composeProject ? ` · ${container.composeProject}` : ""}{container.restartPolicy ? ` · 重启：${container.restartPolicy}` : ""}{container.cpuLimitNano ? ` · ${(container.cpuLimitNano / 1_000_000_000).toFixed(2)} 核` : ""}{container.memoryLimitBytes ? ` · ${formatBytes(container.memoryLimitBytes)} 内存` : ""}</small></div><div className="docker-container-ports"><span className="docker-label">端口</span><strong className="mono">{container.ports || "—"}</strong></div><div className="docker-actions docker-actions--primary">{running ? <Button variant="ghost" size="sm" onClick={() => onAction("stop")}><Square size={13} /> 停止</Button> : <Button variant="primary" size="sm" onClick={() => onAction("start")}><Play size={13} /> 启动</Button>}<Button variant="ghost" size="sm" onClick={() => onAction("restart")}><RotateCw size={13} /> 重启</Button><Button variant="ghost" size="sm" onClick={onLogs}><FileText size={13} /> 日志</Button>{publishedPort && <Button variant="ghost" size="sm" onClick={() => onOpenPort(publishedPort)}><ExternalLink size={13} /> 打开</Button>}<details className="docker-more"><summary>更多</summary><div className="docker-more__menu"><Button variant="ghost" size="sm" onClick={() => { const nextName = window.prompt("重命名为", container.name); if (nextName?.trim() && nextName.trim() !== container.name) onAction("rename", nextName.trim()); }}><RotateCw size={13} /> 重命名</Button><Button variant="ghost" size="sm" onClick={() => void navigator.clipboard?.writeText(container.id)}><Copy size={13} /> 复制 ID</Button><Button variant="ghost" size="sm" onClick={() => void navigator.clipboard?.writeText(container.name)}><Copy size={13} /> 复制名称</Button>{running && <Button variant="ghost" size="sm" onClick={() => onAction(paused ? "unpause" : "pause")}><Pause size={13} /> {paused ? "继续运行" : "暂停"}</Button>}<Button variant="danger" size="sm" onClick={() => onAction("kill")}><Square size={13} /> 强制结束</Button><Button variant="ghost" size="sm" onClick={onFollow}><RefreshCw size={13} /> 跟随日志</Button><Button variant="ghost" size="sm" onClick={onExec}><SquareTerminal size={13} /> 执行命令</Button><Button variant="ghost" size="sm" onClick={() => onDetail("inspect")}><Code2 size={13} /> 检查详情</Button><Button variant="ghost" size="sm" onClick={() => onDetail("stats")}><Activity size={13} /> 资源统计</Button><Button variant="ghost" size="sm" onClick={() => onDetail("top")}><ListTree size={13} /> 进程列表</Button><Button variant="danger" size="sm" onClick={() => onAction("remove")}><Trash2 size={13} /> 删除</Button></div></details></div></div></article>;
}

/** 复用服务器工作区导航，并标记当前 Docker 页。 */
function DockerTabs({ serverId }: { serverId: string }) { return <nav className="workspace-tabs"><NavLink to={`/servers/${serverId}`}>概览</NavLink><NavLink to={`/servers/${serverId}/files`}>文件</NavLink><NavLink to={`/servers/${serverId}/terminal`}>终端</NavLink><NavLink to={`/servers/${serverId}/operations`}>端口与进程</NavLink><NavLink to={`/servers/${serverId}/services`}>服务</NavLink><NavLink to={`/servers/${serverId}/tools`}>工具</NavLink><NavLink to={`/servers/${serverId}/logs`}>日志</NavLink><NavLink to={`/servers/${serverId}/nginx`}>Nginx</NavLink><NavLink className="active" to={`/servers/${serverId}/docker`}>Docker</NavLink></nav>; }
